using System;
using UnityEngine;

namespace Game.Runtime
{
    /// <summary>
    /// Tracks a damage-over-time effect. Call <see cref="Apply"/> to start it and
    /// <see cref="Tick"/> every frame (or from a test) to advance it.
    /// </summary>
    public class DamageOverTimeEffect : MonoBehaviour
    {
        private int _damagePerSecond;
        private float _duration;
        private float _elapsed;
        private float _fractionalDamage;
        private bool _isActive;

        public event Action<int> DamageApplied;
        public event Action Completed;

        public bool IsActive => _isActive;
        public float Elapsed => _elapsed;
        public float Duration => _duration;

        /// <summary>Starts (or restarts) the effect. Negative inputs are clamped to zero.</summary>
        public void Apply(int damagePerSecond, float duration)
        {
            _damagePerSecond = Mathf.Max(0, damagePerSecond);
            _duration = Mathf.Max(0f, duration);
            _elapsed = 0f;
            _fractionalDamage = 0f;
            _isActive = _damagePerSecond > 0 && _duration > 0f;
        }

        /// <summary>Advances the effect by deltaTime, raising DamageApplied for whole-point damage.</summary>
        public void Tick(float deltaTime)
        {
            if (!_isActive)
            {
                return;
            }

            float clampedDelta = Mathf.Max(0f, deltaTime);
            float remaining = _duration - _elapsed;
            float step = Mathf.Min(clampedDelta, remaining);

            _elapsed += step;
            _fractionalDamage += _damagePerSecond * step;

            int wholeDamage = Mathf.FloorToInt(_fractionalDamage);
            if (wholeDamage > 0)
            {
                _fractionalDamage -= wholeDamage;
                DamageApplied?.Invoke(wholeDamage);
            }

            if (_elapsed >= _duration)
            {
                _isActive = false;
                Completed?.Invoke();
            }
        }
    }
}
