using System.Collections.Generic;
using NUnit.Framework;
using UnityEngine;
using Game.Runtime;

public class DamageOverTimeEffectTests
{
    [Test]
    public void Apply_Then_FullTick_DealsExactTotalDamage_AndCompletes()
    {
        var go = new GameObject();
        var dot = go.AddComponent<DamageOverTimeEffect>();
        int totalDamage = 0;
        int completedCount = 0;
        dot.DamageApplied += d => totalDamage += d;
        dot.Completed += () => completedCount++;

        dot.Apply(10, 2f);
        dot.Tick(2f);

        Assert.AreEqual(20, totalDamage);
        Assert.AreEqual(1, completedCount);
        Assert.IsFalse(dot.IsActive);

        Object.DestroyImmediate(go);
    }

    [Test]
    public void Tick_PastDuration_DoesNotOverApply()
    {
        var go = new GameObject();
        var dot = go.AddComponent<DamageOverTimeEffect>();
        int totalDamage = 0;
        dot.DamageApplied += d => totalDamage += d;

        dot.Apply(5, 1f);
        dot.Tick(0.5f);
        dot.Tick(0.5f);
        dot.Tick(1f); // extra tick after the effect has already ended

        Assert.AreEqual(5, totalDamage);
        Assert.IsFalse(dot.IsActive);

        Object.DestroyImmediate(go);
    }

    [Test]
    public void PartialTicks_AccumulateWholePoints_WithoutOverOrUnderApplying()
    {
        var go = new GameObject();
        var dot = go.AddComponent<DamageOverTimeEffect>();
        var appliedAmounts = new List<int>();
        dot.DamageApplied += appliedAmounts.Add;

        dot.Apply(3, 1f);
        for (int i = 0; i < 10; i++)
        {
            dot.Tick(0.1f);
        }

        int total = 0;
        foreach (var amount in appliedAmounts)
        {
            Assert.Greater(amount, 0, "DamageApplied should never fire with zero damage.");
            total += amount;
        }

        Assert.AreEqual(3, total);
        Assert.IsFalse(dot.IsActive);

        Object.DestroyImmediate(go);
    }

    [Test]
    public void Apply_ClampsNegativeInputs_AndNeverActivates()
    {
        var go = new GameObject();
        var dot = go.AddComponent<DamageOverTimeEffect>();
        int totalDamage = 0;
        dot.DamageApplied += d => totalDamage += d;

        dot.Apply(-5, -1f);

        Assert.IsFalse(dot.IsActive);

        dot.Tick(1f);

        Assert.AreEqual(0, totalDamage);

        Object.DestroyImmediate(go);
    }

    [Test]
    public void Apply_ZeroDamagePerSecond_NeverDealsDamage()
    {
        var go = new GameObject();
        var dot = go.AddComponent<DamageOverTimeEffect>();
        int totalDamage = 0;
        dot.DamageApplied += d => totalDamage += d;

        dot.Apply(0, 5f);

        Assert.IsFalse(dot.IsActive);

        dot.Tick(5f);

        Assert.AreEqual(0, totalDamage);

        Object.DestroyImmediate(go);
    }
}
